    <script>
        // 时间更新
        function updateTime() {
            const now = new Date();
            const hours = String(now.getHours()).padStart(2, '0');
            const minutes = String(now.getMinutes()).padStart(2, '0');
            const timeString = `${hours}:${minutes}`;

            document.getElementById('status-time').textContent = timeString;
            document.getElementById('lock-time').textContent = timeString;

            const days = ['星期日', '星期一', '星期二', '星期三', '星期四', '星期五', '星期六'];
            const dateString = `${now.getMonth() + 1}月${now.getDate()}日 ${days[now.getDay()]}`;
            document.getElementById('lock-date').textContent = dateString;
        }

        updateTime();
        setInterval(updateTime, 1000);

        // 解锁功能
        const lockScreen = document.getElementById('lock-screen');
        lockScreen.addEventListener('click', () => {
            lockScreen.classList.add('unlocked');
        });

        // 应用管理
        document.querySelectorAll('.app-icon').forEach(app => {
            app.addEventListener('click', () => {
                const appName = app.dataset.app;
                const appScreen = document.getElementById(`${appName}-app`);
                if (appScreen) {
                    appScreen.classList.add('active');
                } else {
                    showNotification(`${app.querySelector('.app-icon-label').textContent}应用暂未开放`);
                }
            });
        });

        function closeApp(appId) {
            document.getElementById(appId).classList.remove('active');
        }

        // 发送命令
        function sendCommand(message) {
            try {
                if (typeof triggerSlash === 'function') {
                    triggerSlash(`/send ${message}|/trigger`);
                    return true;
                }

                const methods = [
                    () => window.triggerSlash?.(`/send ${message}|/trigger`),
                    () => window.parent?.triggerSlash?.(`/send ${message}|/trigger`),
                    () => window.top?.triggerSlash?.(`/send ${message}|/trigger`),
                    () => window.parent?.postMessage({
                        type: 'stt-command',
                        command: `/send ${message}|/trigger`
                    }, '*')
                ];

                for (let method of methods) {
                    try {
                        method();
                        return true;
                    } catch (e) {}
                }

                return false;
            } catch (e) {
                console.error('发送命令失败:', e);
                return false;
            }
        }

        // 通知功能
        function showNotification(message) {
            const notification = document.getElementById('notification');
            notification.textContent = message;
            notification.classList.add('show');

            setTimeout(() => {
                notification.classList.remove('show');
            }, 3000);
        }

        // 短信功能
        const smsInput = document.getElementById('sms-input');
        const smsSend = document.getElementById('sms-send');

        smsInput.addEventListener('input', function() {
            smsSend.disabled = !this.value.trim();
            this.style.height = 'auto';
            this.style.height = Math.min(this.scrollHeight, 100) + 'px';
        });

        function sendSMS() {
            const message = smsInput.value.trim();

            if (message) {
                const messageDiv = document.createElement('div');
                messageDiv.className = 'message sent';
                messageDiv.textContent = message;
                document.getElementById('sms-messages').appendChild(messageDiv);

                if (sendCommand(`（发送短信给幽）${message}`)) {
                    showNotification('短信已发送');
                } else {
                    showNotification('发送失败');
                }

                smsInput.value = '';
                smsInput.style.height = 'auto';
                smsSend.disabled = true;

                const messagesContainer = document.getElementById('sms-messages');
                messagesContainer.scrollTop = messagesContainer.scrollHeight;
            }
        }

        smsInput.addEventListener('keypress', (e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                sendSMS();
            }
        });

        // 导航功能
        let pendingLocation = '';

        function confirmNavigation(location) {
            pendingLocation = location;
            document.getElementById('confirm-message').textContent = `确定要前往 ${location} 吗？`;
            document.getElementById('overlay').classList.add('show');
            document.getElementById('confirm-dialog').classList.add('show');

            // 设置确认按钮的点击事件
            document.getElementById('confirm-ok').onclick = function() {
                navigateTo(pendingLocation);
            };
        }

        function cancelNavigation() {
            document.getElementById('overlay').classList.remove('show');
            document.getElementById('confirm-dialog').classList.remove('show');
            pendingLocation = '';
        }

        function navigateTo(location) {
            if (sendCommand(`前往 ${location}`)) {
                showNotification(`正在前往: ${location}`);
                cancelNavigation(); // 关闭确认对话框
                setTimeout(() => {
                    closeApp('map-app');
                }, 1000);
            } else {
                showNotification('导航失败');
                cancelNavigation();
            }
        }

        // 防止双击缩放
        let lastTouchEnd = 0;
        document.addEventListener('touchend', function(event) {
            const now = Date.now();
            if (now - lastTouchEnd <= 300) {
                event.preventDefault();
            }
            lastTouchEnd = now;
        }, false);

        // 防止捏合缩放
        document.addEventListener('touchstart', function(event) {
            if (event.touches.length > 1) {
                event.preventDefault();
            }
        }, { passive: false });

        console.log('魔法手机界面加载完成');
    </script>
</body>
</html>
